{"ok": true, "output": {"customer": {"balance": 1250.0, "name": "Asha", "status": "open"}, "customer_id": 101, "found": true}, "tool": "query_db", "tool_use_id": "call_003"}
{"error": {"message": "field 'customer_id': expected integer, got 'banana'", "type": "validation_error"}, "ok": false, "tool": "query_db", "tool_use_id": "call_004"}
